 public static string Main(){var w=KitPS1.World;var root=WorldGenerator.FindRoot(w);var td=root.GetComponentInChildren<Terrain>().terrainData;var original=td.GetAlphamaps(0,0,td.alphamapWidth,td.alphamapHeight);var layerIds=td.terrainLayers.Select(x=>AssetDatabase.AssetPathToGUID(AssetDatabase.GetAssetPath(x))).ToArray();var paint=(float[,,])original.Clone();for(int z=20;z<25;z++)for(int x=20;x<25;x++)for(int l=0;l<4;l++)paint[z,x,l]=l==2?1:0;td.SetAlphamaps(0,0,paint);foreach(var tex in td.alphamapTextures)EditorUtility.SetDirty(tex);EditorUtility.SetDirty(td);AssetDatabase.SaveAssets();var expected=td.GetAlphamaps(0,0,td.alphamapWidth,td.alphamapHeight).Cast<float>().ToArray();var baseline=w.baseTerrain.GetHeights(0,0,w.resolution,w.resolution).Cast<float>().ToArray();var manual=KitPS1.Place("Rock_1",new Vector3(20,2,3));manual.transform.rotation=Quaternion.Euler(0,37,0);manual.transform.localScale=Vector3.one*1.3f;var pos=manual.transform.position;WorldGenerator.Apply(w);WorldGenerator.Apply(w);bool preserved=expected.SequenceEqual(td.GetAlphamaps(0,0,td.alphamapWidth,td.alphamapHeight).Cast<float>())&&layerIds.SequenceEqual(td.terrainLayers.Select(x=>AssetDatabase.AssetPathToGUID(AssetDatabase.GetAssetPath(x))));bool objects=manual&&manual.transform.position==pos&&manual.transform.localScale==Vector3.one*1.3f;bool baseIntact=baseline.SequenceEqual(w.baseTerrain.GetHeights(0,0,w.resolution,w.resolution).Cast<float>());Undo.IncrementCurrentGroup();int group=Undo.GetCurrentGroup();KitPS1.ResetPaint(w);Undo.CollapseUndoOperations(group);Undo.FlushUndoRecordObjects();Undo.PerformUndo();bool undo=expected.SequenceEqual(td.GetAlphamaps(0,0,td.alphamapWidth,td.alphamapHeight).Cast<float>());UnityEngine.Object.DestroyImmediate(manual);td.SetAlphamaps(0,0,paint);foreach(var tex in td.alphamapTextures)EditorUtility.SetDirty(tex);EditorUtility.SetDirty(td);AssetDatabase.SaveAssets();var scene=SceneManager.GetActiveScene();EditorSceneManager.SaveScene(scene);EditorSceneManager.OpenScene(scene.path);w=KitPS1.World;td=WorldGenerator.FindRoot(w).GetComponentInChildren<Terrain>().terrainData;bool reload=expected.SequenceEqual(td.GetAlphamaps(0,0,td.alphamapWidth,td.alphamapHeight).Cast<float>());td.SetAlphamaps(0,0,original);foreach(var tex in td.alphamapTextures)EditorUtility.SetDirty(tex);EditorUtility.SetDirty(td);AssetDatabase.SaveAssets();var textures=KitPS1.Surfaces.Select(n=>{var tex=AssetDatabase.LoadAssetAtPath<Texture2D>(KitPS1.Art+"/"+n+".png");return new{name=n,width=tex.width,height=tex.height,filter=tex.filterMode.ToString()};}).ToArray();bool pixels=textures.All(x=>x.width<=64&&x.height<=64&&x.filter=="Point");var result=new{preserved,objects,baseIntact,undo,reload,pixels,textures,issues=WorldValidation.Issues(w)};string json=Unity.Plastic.Newtonsoft.Json.JsonConvert.SerializeObject(result, Unity.Plastic.Newtonsoft.Json.Formatting.Indented);Directory.CreateDirectory("../Artifacts/KitPS1_022");File.WriteAllText("../Artifacts/KitPS1_022/validation.json",json);if(!preserved||!objects||!baseIntact||!undo||!reload||!pixels)throw new Exception(json);KitPS1Window.Open();return json;}
